    h, w = len(grid), len(grid[0]) if grid else 0
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                pieces.append((1, box))
            for missing, color in [((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                shape = box - {missing}
                if shape <= cells:
                    pieces.append((color, shape))

    by_cell = {cell: [] for cell in cells}
    for color, shape in pieces:
        for cell in shape:
            by_cell[cell].append((color, shape))

    # Exact cover; choose the uncovered cell with the fewest viable pieces.
    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for _, shape in by_cell[p]))
        for color, shape in by_cell[cell]:
            if shape <= remaining:
                rest = solve(remaining - shape)
                if rest is not None:
                    return [(color, shape)] + rest
        return None

    tiling = solve(cells)
    if tiling is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for color, shape in tiling:
